 public override bool BroadcastParticipantActive(int slot)=>slot==rules.Active;
 public override void DescribeBroadcast(SportsBroadcastAction a,SportsBroadcastFraming f){a.primary=rules.Active;if(course.checkpoints.Length>0)a.Objective(course.checkpoints[Mathf.Clamp(rules.Checkpoint,0,course.checkpoints.Length-1)],1.5f);a.reason="ACTIVE ATHLETE / NEXT OBSTACLE";}
  public LWS.TruckFieldGoal.FieldGoalCrowd crowd;public NinjaCourse course;public SportsEventTruck[] trucks;public NinjaAthlete[] athletes;public SportsFragmentRig[] fragments;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public SportsCameraFit framing;public SportsChaosWeather atmosphere;public SportsRecordedReview review;public NinjaRules rules=new NinjaRules();[HideInInspector]public Key compressionKey=Key.LeftCtrl;public int ActualBells{get;private set;}public int ActualRecoveries{get;private set;}
  public override string Title=>"TRUCK NINJA WARRIOR";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override int OptionCount=>3;public override int WeatherCount=>1;public override int CompactScoreColumns=>8;public override bool SupportsSplitAIViews=>true;public override bool AISplitViewsApplicable=>false;public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>rules.Phase==NinjaPhase.Countdown?3-rules.StateClock:-1;public override float RaceStartSeconds=>rules.Phase==NinjaPhase.Running?rules.Clock:-1;public override bool ReplayControls=>review!=null&&review.Playing;
  public override void NormalizeSetup(){base.NormalizeSetup();setup.mode=BowlingMode.HotSeat;setup.sharedHotSeat=true;}public override string OptionLabel=>new[]{"THREE-MINUTE RUN","TWO-AND-A-HALF-MINUTE RUN","TWO-MINUTE RUN"}[option];
  public override string Header=>Title+" · "+setup.players[rules.Active].name+" · "+Mathf.Max(0,rules.Limit-rules.Clock).ToString("F1")+"s LEFT";
  public override string Status=>rules.Phase==NinjaPhase.Countdown?"SQUAT. SPRING. SOAR. · GET READY":announcementUntil>age?announcement:rules.Checkpoint>=course.obstacles.Length?"WARPED WALL CLEAR · HIT THE GIANT BELL WITH YOUR BUMPER":course.obstacles[rules.Checkpoint]+" · "+rules.Clock.ToString("F1")+"s";
  public override string ControlCaption(int slot)=>base.ControlCaption(slot).Replace(" ACTION"," JUMP")+" · HOLD TO CHARGE / RELEASE TO JUMP";
  public override string Help=>"Six substantial physical game-show obstacles: tilting steps, rotating logs, swinging wrecking balls, a weight-driven seesaw bridge, spinning discs and the giant curved warped wall. Drive and brake with your assigned source. Hold the existing JUMP input to compress actual NWH suspension and charge; release to launch. A tap gives a short jump, a full charge a higher jump with bounded forward takeoff help. There is no separate boost or compression button. While airborne, forward/back pitches, left/right rolls with limited yaw, and upright assistance helps landing alignment. Gravity and existing momentum remain real. Each obstacle's whole-truck exit records ordered course progress. A fall or prolonged overturn restarts this athlete at the very beginning, clears the attempt timer and obstacle progress, resets the obstacles and replays3–2–1–GO. There is NO fall-time penalty and no intermediate respawn. The2–3minute limit still ends an uncompleted attempt as DNF; completed or timed-out turns advance to the next athlete. Complete the curved wall and physically hit the giant bell with your front bumper. Fastest completed-attempt time wins; equal times compare falls then share placing. Failed runs rank by current obstacles cleared.1–8alternating participants, up to4humans, AI, full-screen active-driver chase/cab/elevated views, free look, horn, crew identities, selected weather, recorded highlights and rematch. AI uses the same held/released jump, physical course and restart rules; no invented scores.";
  public override bool ValidateSources(out string reason)=>base.ValidateSources(out reason);
  public override float ParticipantProgress(int slot)=>slot==rules.Active&&rules.Phase==NinjaPhase.Running&&athletes[slot].Charging?athletes[slot].Charge:-1;
  public override bool TryReadScoreCard(int i,out string value,out string detail){value=rules.finished[i]?rules.adjustedTime[i].ToString("F1")+"s":i==rules.Active?rules.Clock.ToString("F1")+"s":"—";detail=rules.finished[i]?"FINISH · "+rules.falls[i]+" FALLS":i==rules.Active&&athletes[i].Charging?"JUMP CHARGE "+(athletes[i].Charge*100).ToString("F0")+"%":rules.cleared[i]+" / "+course.obstacles.Length+" CLEARED";return i<setup.count;}
  readonly StringBuilder text=new StringBuilder(900);public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append('#').Append(rules.Place(i)).Append(' ').Append(setup.players[i].name).Append(" · ").Append(rules.finished[i]?rules.adjustedTime[i].ToString("F2")+"s":"DNF").Append(" · ").Append(rules.cleared[i]).Append(" OBSTACLES · ").Append(rules.falls[i]).Append(" FALLS\n");return text.ToString();}}public override string Results=>"GAME-SHOW FINAL TIMES\n\n"+Standings;
  readonly FareFightRoute driver=new FareFightRoute();readonly NinjaProgressWatch recoveryProgress=new NinjaProgressWatch();int prepared=-1;float age,announcementUntil,recoveryUntil;string announcement="";float priorRear,stuckFor;float lastJumpZ=-1000;readonly float[] jumpZones={2,34,62,89,134,176,225,359,422,485,519,642};
  protected override void Awake(){base.Awake();rules.FinishConfirmed+=ConfirmFinish;}
  protected override void OnDestroy(){rules.FinishConfirmed-=ConfirmFinish;base.OnDestroy();}
  void ConfirmFinish(int slot,float seconds){if(float.IsFinite(seconds)&&seconds>=0)ConfirmOutcome("finish:"+slot,slot,seconds,"COURSE CLEARED");}
  protected override void BeginGame(){fallPresentation?.ClearFallPresentation();rules.Reset(setup.count,course.obstacles.Length,new[]{180f,150,120}[option]);rules.Begin();age=0;announcement="";announcementUntil=0;feedback.StopAll();crowd?.ResetAttempt();ActualBells=ActualRecoveries=0;prepared=-1;atmosphere.Configure(Environment.TickCount,0,1);if(review==null){review=gameObject.AddComponent<SportsRecordedReview>();review.match=this;review.trucks=trucks;review.fragments=fragments;review.drivingViews=drivingViews;review.broadcast=broadcast;review.framing=framing;review.atmosphere=atmosphere;review.watchAction="watchninja";review.extras=new[]{course.motionGroup};}review.ResetRecord();Prepare();}
  void Prepare(){prepared=rules.Active;course.ResetCourse();recoveryUntil=stuckFor=0;lastJumpZ=-1000;driver.Reset();driver.groundNormalThreshold=.4f;driver.speedScale=12f/(setup.players[rules.Active].difficulty==BowlingDifficulty.Easy?9:setup.players[rules.Active].difficulty==BowlingDifficulty.Normal?12:15);for(int i=0;i<trucks.Length;i++)trucks[i].gameObject.SetActive(i==rules.Active);var t=trucks[rules.Active];fragments[rules.Active].ResetBody();t.tractorMotor.Configure();var damage=t.GetComponent<NWH.VehiclePhysics2.Damage.DamageHandler>();if(damage!=null){damage.meshDeform=false;damage.Repair();}athletes[rules.Active].ResetAthlete();t.Prepare(course.start,Quaternion.identity);Hold(t);var groups=new int[setup.count];Array.Fill(groups,rules.Active);drivingViews.rally.presentationGroups=groups;drivingViews.rally.Focus=rules.Active;drivingViews.Layout();priorRear=Rear(t);recoveryProgress.Reset(t.body.position);Gate();Physics.SyncTransforms();broadcast.broadcastFraming?.Release();}
  static float Rear(SportsEventTruck t){float z=float.PositiveInfinity;foreach(var c in t.GetComponentsInChildren<Collider>())if(c.enabled&&!c.isTrigger&&c.attachedRigidbody==t.body)z=Mathf.Min(z,c.bounds.min.z);return z;}
  static void Hold(SportsEventTruck t){t.TickDrive(Vector2.zero);var input=t.tractorMotor.vehicle.input;input.states.handbrake=input.states.handbrakeRaw=1;}
  protected override void Simulate(float dt)
  {
   age+=dt;var before=rules.Phase;rules.Tick(dt);if(rules.Complete){EndMatch();return;}if(prepared!=rules.Active)Prepare();if(before==NinjaPhase.Countdown&&rules.Phase==NinjaPhase.Running)course.Release();atmosphere.Tick(age);if(rules.Phase==NinjaPhase.Running)course.Step(rules.Clock);review.Capture(age);var t=trucks[rules.Active];if(rules.Phase!=NinjaPhase.Running){Hold(t);return;}
   bool aiSource=setup.players[rules.Active].source==BowlingSource.AI;recoveryProgress.Step(t.body.position,dt);stuckFor=recoveryProgress.Seconds;bool water=t.body.position.y<course.waterLevel+1||Mathf.Abs(t.body.position.x)>65;bool trapped=stuckFor>6&&(aiSource||t.transform.up.y<.25f);
   if(water||trapped){if(age>=recoveryUntil)RestartAttempt(t,water?"SPLASH!":"OVERTURNED / STUCK");return;}
   float rear=Rear(t);if(rules.Checkpoint<course.checkpoints.Length){var point=course.checkpoints[rules.Checkpoint];if(priorRear<point.z&&rear>=point.z&&t.body.position.y>=point.y-2&&Mathf.Abs(t.body.position.x-point.x)<20){rules.Clear(rules.Active,rules.Checkpoint+1);feedback.PlayAt(1,t.body.position,0,false);crowd?.React(true,"CHECKPOINT",t.body.position);Announce("OBSTACLE "+rules.Checkpoint+" CLEARED");}}
   bool jumpHeld=!aiSource&&setup.players[rules.Active].released&&ActionHeld(rules.Active);var command=aiSource?Bot(t,out jumpHeld,dt):commands[rules.Active];bool jumpPressed=!aiSource&&setup.players[rules.Active].released&&actions[rules.Active];t.tractorMotor.gripScale=atmosphere.Grip;athletes[rules.Active].Step(command,jumpHeld,jumpPressed,dt,rules.Clock);priorRear=rear;
  }
  void RestartAttempt(SportsEventTruck t,string reason){if(!rules.Fall(rules.Active))return;ActualRecoveries++;crowd?.React(false,"FALL",t.body.position);AttemptRestarting?.Invoke(t,reason=="SPLASH!");Prepare();recoveryUntil=age+1.2f;Announce(reason+" · NEW ATTEMPT FROM THE START");}
  Vector2 Bot(SportsEventTruck t,out bool jumpHeld,float dt)
  {
   var target=rules.Checkpoint<course.checkpoints.Length?course.checkpoints[rules.Checkpoint]+Vector3.forward*5:course.bell.position;driver.DirectGoal(t.body.position,target);Rigidbody permitted=rules.Checkpoint==5?course.finaleLanding:rules.Checkpoint>=6?course.bell:null;if(rules.Checkpoint==0){float nearest=float.PositiveInfinity;foreach(var body in course.movingBodies)if(body.name.StartsWith("Weight-tilting giant step")&&body.position.z>t.body.position.z+2&&body.position.z<nearest){nearest=body.position.z;permitted=body;}}var command=driver.Drive(t.body,t.transform,(int)setup.players[rules.Active].difficulty,dt,atmosphere.Grip,permitted,rules.Checkpoint==5?course.warpedWall:null);jumpHeld=false;
   bool ground=Array.Exists(t.wheels,w=>w.IsGrounded);float z=t.body.position.z,launch=float.PositiveInfinity;foreach(float at in jumpZones)if(at>lastJumpZ+.5f&&at>=z-2){launch=at;break;}if(rules.Checkpoint==3&&lastJumpZ==359&&z<372)launch=372;float distance=launch-z;
   // Choose real launch edges from the authored course. These are input
   // decisions: the athlete still requires grounded wheels, charge and cooldown.
   // Counter the measured sideways motion of genuine rolling/spinning decks
   // through ordinary steering. No lateral force or position correction.
   if(ground&&(rules.Checkpoint==1||rules.Checkpoint==4)){float centre=rules.Checkpoint==1?0:Mathf.Clamp((z-510)/34*4,-4,4);command.x=Mathf.Clamp(command.x-t.body.linearVelocity.x*.2f-(t.body.position.x-centre)*.06f,-.8f,.8f);}
   bool needsSuper=launch==89||launch==422||launch==642;
   if(ground&&distance<(needsSuper?12:4)){var athlete=athletes[rules.Active];bool ready=athlete.Charging&&athlete.Charge>=(needsSuper?.85f:.08f);if(distance<3&&ready){jumpHeld=false;lastJumpZ=launch;}else{jumpHeld=true;if(needsSuper&&distance<2&&!ready)command.y=-.25f;}}
   return command;
  }
  public void StrikeBell(int slot){if(!Live||!rules.Bell(slot))return;ActualBells++;crowd?.React(true,"VICTORY BELL",course.bell.position);float best=SportsPrefs.GetFloat("TruckNinjaWarrior.BestSeconds",float.PositiveInfinity);if(rules.adjustedTime[slot]<best){SportsPrefs.SetFloat("TruckNinjaWarrior.BestSeconds",rules.adjustedTime[slot]);SportsPrefs.Save();}feedback.PlayAt(6,course.bell.position,0,true);Announce("DING! "+setup.players[slot].name+" · "+rules.adjustedTime[slot].ToString("F2")+"s");}
  public string DriveTelemetry=>"desired="+driver.DesiredSpeed+" obstacle="+driver.BlockingObstacle+" stationary="+recoveryProgress.Seconds;
  void Announce(string value){announcement=value;announcementUntil=age+3;}
  protected override void Present(float dt){if(drivingViews==null)return;if(fallPresentation!=null&&fallPresentation.TryPresentFall(dt))return;if(ReplayControls){review.Tick();return;}drivingViews.Tick(dt);if(drivingViews.NeedsArena){var t=trucks[rules.Active];broadcast.Pose(t.body.position+Vector3.forward*9,new Vector3(25,23,-31),69);}}
  public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();else review?.Action(key);}protected override void SetPaused(bool pause){atmosphere?.Pause(pause);if(pause&&athletes!=null)foreach(var athlete in athletes)athlete.CancelCharge();}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}
  protected override void StopGame(){fallPresentation?.ClearFallPresentation();review?.End(false);StopSounds();if(athletes!=null)foreach(var a in athletes)a.CancelCharge();if(trucks!=null)foreach(var t in trucks){t.Power(false);if(!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=true;}}
